CREATE DATABASE IF NOT EXISTS sanskriti_canvas; USE sanskriti_canvas; CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('user','admin') DEFAULT 'user'); CREATE TABLE IF NOT EXISTS categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) UNIQUE NOT NULL); CREATE TABLE IF NOT EXISTS heritage(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,state VARCHAR(100),district_city VARCHAR(100),category_id INT,description TEXT,history TEXT,cultural_significance TEXT,image VARCHAR(255),source VARCHAR(500),status ENUM('approved','pending','rejected') DEFAULT 'approved',FOREIGN KEY(category_id) REFERENCES categories(id)); CREATE TABLE IF NOT EXISTS contributions(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,name VARCHAR(180) NOT NULL,state VARCHAR(100),district_city VARCHAR(100),category VARCHAR(80),description TEXT,significance TEXT,source VARCHAR(500),status ENUM('pending','approved','rejected') DEFAULT 'pending',FOREIGN KEY(user_id) REFERENCES users(id)); INSERT IGNORE INTO categories(name) VALUES ('Heritage'),('Culture'),('Food'),('Festival');